window.__votdWeek && window.__votdWeek({"week":"2028-10-16","reading":"3 Nephi 27–4 Nephi","days":[{"d":"2028-10-16","ref":"3 Nephi 27:20","b":"3 Nephi","c":27,"v":20,"he":"וְעַתָּה זֹאת הַמִּצְוָה שׁוּבוּ כׇּל־אַפְסֵי־אָרֶץ וּבֹאוּ אֵלַי וְהִטָּבְלוּ בִּשְׁמִי לְמַעַן תִּתְקַדְּשׁוּ בְּקַבָּלַת רוּחַ־הַקֹּדֶשׁ לְמַעַן תַּעַמְדוּ בְּלִי־מוּם לְפָנַי בַּיּוֹם הָאַחֲרוֹן׃","en":"Now this is the commandment: Repent, all ye ends of the earth, and come unto me and be baptized in my name, that ye may be sanctified by the reception of the Holy Ghost, that ye may stand spotless before me at the last day."},{"d":"2028-10-17","ref":"3 Nephi 27:27","b":"3 Nephi","c":27,"v":27,"he":"וּדְעוּ כִּי תִהְיוּ שׁוֹפְטֵי הָעָם־הַזֶּה כַּמִּשְׁפָּט אֲשֶׁר אֶתֵּן לָכֶם אֲשֶׁר יִהְיֶה צֶדֶק לָכֵן אֵיזֶה אֲנָשִׁים רָאוּי לָכֶם לִהְיוֹת אָמֵן אֹמֵר אֲנִי לָכֶם כַּאֲשֶׁר אֲנִי׃","en":"And know ye that ye shall be judges of this people, according to the judgment which I shall give unto you, which shall be just. Therefore, what manner of men ought ye to be? Verily I say unto you, even as I am."},{"d":"2028-10-18","ref":"3 Nephi 28:1","b":"3 Nephi","c":28,"v":1,"he":"וַיְהִי כְּדַבֵּר יֵשׁוּעַ אֶת־הַדְּבָרִים הָאֵלֶּה וַיְדַבֵּר אֶל־תַּלְמִידָיו אֶחָד אֶחָד לֵאמֹר מַה־תַּחְפְּצוּ מִמֶּנִּי אַחֲרֵי לֶכְתִּי אֶל־הָאָב׃","en":"And it came to pass when Jesus had said these words, he spake unto his disciples, one by one, saying unto them: What is it that ye desire of me, after that I am gone to the Father?"},{"d":"2028-10-19","ref":"3 Nephi 28:19","b":"3 Nephi","c":28,"v":19,"he":"וַיֻּשְׁלְכוּ לַכֶּלֶא בִּידֵי אֲשֶׁר לֹא־הָיוּ מִן־הַקְּהִלָּה וְלֹא יָכְלוּ בָּתֵּי הַכֶּלֶא לַעֲצֹר אוֹתָם כִּי נִבְקְעוּ לִשְׁנַיִם׃","en":"And they were cast into prison by them who did not belong to the church. And the prisons could not hold them, for they were rent in twain."},{"d":"2028-10-20","ref":"3 Nephi 29:5","b":"3 Nephi","c":29,"v":5,"he":"אוֹי לְמִי הַבָּז לְמַעֲשֵׂי יְהוָה אַף אוֹי לְמִי אֲשֶׁר יְכַחֵשׁ בַּמָּשִׁיחַ וּבְמַעֲשָׂיו׃","en":"Wo unto him that spurneth at the doings of the Lord; yea, wo unto him that shall deny the Christ and his works!"},{"d":"2028-10-21","ref":"4 Nephi 1:3","b":"4 Nephi","c":1,"v":3,"he":"וַיְהִי כׇל־דָּבָר יַחְדָּו בֵּינֵיהֶם וְעַל־כֵּן לֹא־הָיוּ עֲשִׁירִים וַעֲנִיִּים עֲבָדִים וּבְנֵי־חוֹרִין כִּי הָיוּ כֻלָּם בְּנֵי־חוֹרִין וְנוֹחֲלֵי מַתַּת שָׁמָיִם׃","en":"And they had all things common among them; therefore there were not rich and poor, bond and free, but they were all made free, and partakers of the heavenly gift."},{"d":"2028-10-22","ref":"4 Nephi 1:26","b":"4 Nephi","c":1,"v":26,"he":"וַיָּחֵלּוּ לְהִתְחַלֵּק לְמַעֲמָדוֹת וַיָּחֵלּוּ לְהָקִים לָהֶם קְהִלּוֹת לְמַעַן בֶּצַע וַיָּחֵלּוּ לְהִתְכַּחֵשׁ לִקְהִלַּת הַמָּשִׁיחַ הָאֲמִתִּית׃","en":"And they began to be divided into classes; and they began to build up churches unto themselves to get gain, and began to deny the true church of Christ."}]});
